import os as _benchmark_os
"""Publish aggregate evidence only; retain source questions and raw answers locally."""
from pathlib import Path
import json,shutil
ROOT=Path(_benchmark_os.environ.get('MATHTUTOR_BENCHMARK_ROOT', str(Path(__file__).resolve().parents[1])))
def pc(x):return f'{100*x:.2f}%'
def main():
 repo=ROOT.parents[1]/'MathTutor';summary=json.loads((ROOT/'report/summary.json').read_text());four=json.loads((ROOT/'report/four_benchmarks.json').read_text());headline=json.loads((ROOT/'report/headline.json').read_text());candidate=headline['selected_run'];a=summary['baseline']['test'];b=summary[candidate]['test'];figs=['four_benchmarks_weakness_lines','four_benchmarks_lines','capability_profile_lines','test_metrics_lines','teaching_quality_lines','development_iterations','format_diagnostics_lines'];assets=repo/'docs/eval/assets/opensource-20261016';assets.mkdir(parents=True,exist_ok=True)
 for name in figs:
  for ext in ['png']:shutil.copy2(ROOT/'report'/f'{name}.{ext}',assets/f'{name}.{ext}')
 lines=['# 四套开源基准的数学文本评测（2026-10-16）','',f'同一 DeepSeek Flash、真实 MathTutor WebSocket 入口、单次生成。基线 `{json.loads((ROOT/"sources/candidate_r2.json").read_text())["baseline_commit"][:7]}`；采纳代码 `{headline["product_commit"][:7]}`。独立评审为 Claude Opus 4.7。80 条开发题、原 312 条测试题；评分前依题干隔离 1 条近重复题，主要分析 311 条。','', '## 四套基准折线图','', '![四套基准](assets/opensource-20261016/four_benchmarks_lines.png)','', '四个点对应四套基准，两条线对应本项目基线与改进版。统一纵轴是数学正确、回应学生、可执行性、指令遵循、披露适当、尊重语气六项标准的平均满足率；它是本次适配指标，不是原基准官方总分。MathTutorBench 此图仅含四类教学回应任务，五类客观任务另列。各源题型与难度分布不同，不能把四点排序解释为难度校准后的能力排名。','', '| 基准 | 教学回应 n | 基线六项均值 | 改进版六项均值 | 改进版数学正确项 |','|---|---:|---:|---:|---:|']
 for source,label in [('MTB','MathTutorBench'),('MathDial','MathDial'),('MRBench','MRBench'),('TutorBench','TutorBench')]:
  x=four['baseline'][source];y=four[candidate][source];lines.append(f'| {label} | {y["n"]} | {pc(x["quality"])} | {pc(y["quality"])} | {pc(y["criteria"]["math_correct"])} |')
 lines+=['', '![六维能力](assets/opensource-20261016/capability_profile_lines.png)','', '## 从结果看优势和弱势','', '![薄弱维度](assets/opensource-20261016/four_benchmarks_weakness_lines.png)','', '高阶数学没有随综合分同步提升：统计数学正确项维持 73.91%；微积分从 91.67% 降至 87.50%，适量披露从 100% 降至 75%。MRBench 数学正确项从 87.50% 降至 83.33%。这些均为模型评审下的小样本观察；TutorBench 加权细则差值的题组区间包含零，尚不能证明稳定收益。','', f'教学六项均值整体为 {pc(headline["quality_baseline"])} → {pc(headline["quality_candidate"])}；TutorBench 学科加权细则为 {pc(headline["tutorbench_baseline"])} → {pc(headline["tutorbench_candidate"])}。两个口径分别报告，不混合为 mAP。','', '直接数值解题是本轮较强项：明确最终标记诊断为 23/24（95.83%），与基线相同。清除无关追加练习、尊重当前语言和请求等通用修改，改善了部分指令和输出格式表现；不能把解析分数提升全解释为推理提升。','', '弱项包括对历史计算的重新核验、学生误解的准确识别，以及严格短格式输出。例：统计题 470 的组合数解释清楚，却沿用了历史说明中的错误小数；二项近似下独立计算约 0.91404556，回答给出约 0.912。产品验证器会标注无法自动核对的式子，不保证所有显示计算均已核验。', '', '纠错最终标记诊断为 20/24 → 19/24。4 条由对变零的样本均因最终句含多个数值而不可解析，可见结果本身正确；因此这个下降不证明真实纠错能力退步。原分数仍保留，没有在看过测试后修改解析规则重报高分。严格 Yes/No 正确率仅 25%，步骤编号正确率为 58.33%；上游部分错误标签还对应未完整显示的学生解答，不能把所有零分简单归咎于智能体。','', '![原生分项](assets/opensource-20261016/test_metrics_lines.png)','', '## 迭代与边界','', '![开发迭代](assets/opensource-20261016/development_iterations.png)','', '三轮策略均完整保留。第 2 轮开发教学综合分最高，冻结并采纳；第 3 轮退步后回退。所有候选都未满足预设的 TutorBench 开发加权细则 +5 个百分点门槛，`passed_all_guards=false`。不能称为通过全部教学质量发布门。采纳代码本地相关回归 172 项与安全回归 92 项通过；[三平台 CI 均通过](https://github.com/coscatld/MathTutor/actions/runs/38859132980)。','', '模型评审不是人类评分或学生学习增益。校准仅有 6 个上下文、54 条原回应，语气和错误定位维度的一致性较弱。没有与竞品做同题对照，没有运行原 Qwen 教学奖励模型，也没有 MathDial 互动 Success@k。','', '只评测数学文本固定样本；TutorBench 图片与非数学题未纳入。本轮没有可靠的中国年级标签，因此按基准与任务绘图，不制造一至十二年级的结果。部分 AP 微积分和统计内容超过中国高中共同课程范围。公开题库可能有预训练污染；题组 bootstrap 区间也不覆盖远端模型单次生成随机性。','', '下一轮优先补充可独立核验的新开发材料，改进历史算式复核、条件检查、误解定位及响应协议。本轮测试已解封，后续需重新封存测试题组，不能针对本批题不断调参后继续称其为未见测试。','', '## 复现与来源','', '[工具、协议、评分边界与数据来源许可](../../benchmarks/opensource/README.md)。本地完整归档保留固定输入、金标准、所有原始输出、未采纳代码、评审与评分记录；公开仓库仅发布汇总及工具，不重新分发许可未明确的数据。','', '- [MathTutorBench](https://github.com/eth-lre/mathtutorbench)','- [MathDial](https://github.com/eth-nlped/mathdial)','- [MRBench](https://github.com/kaushal0494/UnifyingAITutorEvaluation)','- [TutorBench](https://huggingface.co/datasets/ScaleAI/TutorBench)','']
 target=repo/'docs/eval/OPEN_SOURCE_BENCHMARK_20261016.md';target.write_text('\n'.join(lines))
 readme=repo/'README.md';text=readme.read_text();start='<!-- OPEN_SOURCE_BENCHMARK_20261016 -->';end='<!-- /OPEN_SOURCE_BENCHMARK_20261016 -->';block=f'''{start}
2026-10-16 新增四套开源基准的数学文本固定样本评测：主要测试 311 条，统一六项教学标准满足率 {pc(headline['quality_baseline'])} → {pc(headline['quality_candidate'])}；TutorBench 加权细则 {pc(headline['tutorbench_baseline'])} → {pc(headline['tutorbench_candidate'])}。明确最终答案的数值解题诊断维持 95.83%，格式改善与数学正确性分别解释。三轮中采纳第 2 轮，第 3 轮退步后回退；预设开发门槛未全部达到。见[四基准折线图、优势弱势与方法边界](docs/eval/OPEN_SOURCE_BENCHMARK_20261016.md)。

![四套开源基准折线图](docs/eval/assets/opensource-20261016/four_benchmarks_lines.png)
{end}'''
 if start in text:text=text[:text.index(start)]+block+text[text.index(end)+len(end):]
 else:text=text.replace('### 我们对比的 benchmark 是什么',block+'\n\n### 我们对比的 benchmark 是什么')
 readme.write_text(text);print(str(target))
if __name__=='__main__':main()
